scwin.onpageunload = function() {

};

scwin.checkVal = function() {
	return WebSquare.wUnit.getJq('#window1_nameLayer_'+$p.id+'window1_subWindow9').hasClass('w2windowContainer_selectedNameLayer');
}
scwin.unitTest = function() {
	//init
	WebSquare.wUnit.start();
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('window1_left').click()");
	WebSquare.wUnit.addCommand("pause", "400");
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
	WebSquare.wUnit.addCommand("pause", "500");
	//Run  and stop
	WebSquare.wUnit.run();
	WebSquare.wUnit.stop();
}
scwin.unitTest()
